# Studyo 0.5.48 yamasi: dipnot cizgisi (Tahrif Hareketleri), tarama dosya adi yer imleri, seslendirmede (sh: N) ve (Bkz: ...)
# Kod klasorunde calistirilir: cd /DATA/AppData/dedplay-studyo/kod/studyo && python3 studyo_0548_yama.py
# Tekrar calistirilabilir: dosya zaten yeniyse ATLANDI; ne eski ne yeniyse hicbir seye dokunmadan HATA.
import base64, hashlib, os, sys, zlib
D = [
    ('kutuphane/kaynak.py', '97b3bef9c8380695681a322cb1ce3fc8', 'd5fa8a9108470d68fdf4957a22e32587',
     ''),
    ('app/ses.py', 'd3f453ad082f27a382441efa2e0bf2bc', '294cdd7fbb870f0ed49aaeeba5737688',
     ''),
    ('kutuphane/main.py', 'ef28e789a45f7390f472f07a0d92d630', 'a7c2663d45d30c801667222ed3442e58',
     ''),
    ('tests/test_0548.py', None, '690039a6fd0f4cb33ab0853bcf511481',
     ''),
]
md5 = lambda p: hashlib.md5(open(p, 'rb').read()).hexdigest() if os.path.exists(p) else None
for yol, eski, yeni, _ in D:
    m = md5(yol)
    if m not in (eski, yeni):
        print('HATA:', yol, 'beklenmeyen icerik (md5', m, ') - hicbir dosya degistirilmedi'); sys.exit(1)
for yol, eski, yeni, veri in D:
    if md5(yol) == yeni:
        print('ATLANDI (zaten yeni):', yol); continue
    icerik = zlib.decompress(base64.b64decode(veri))
    assert hashlib.md5(icerik).hexdigest() == yeni
    open(yol, 'wb').write(icerik)
    print('YAZILDI:', yol, yeni)
print('TAMAM')
